mapper.delete:
delete a from t_cruise_point_instance AS a,t_robot_inspection AS b
        where b.inspection_id = a.cruise_id
        AND b.robot_id = #{robotId, jdbcType=BIGINT}

mapper.select:
select a.robot_id, a.robot_code, a.robot_num, a.robot_name, a.robot_status, a.robot_type, a.robot_ip, a.robot_port, a.light_ip, a.light_port, a.identity_manager, a.lnferad_IP, a.Inferad_Port, a.Inferad_username, a.phote_path, a.create_by, a.create_date, a.update_by, a.update_date, a.robot_factory, a.made_in, a.made_date, a.is_use, a.commission_date, a.up_region_id, a.robot_position , a.drone_position , a.robot_source, a.address, a.building_user, a.appearance_number, a.defect_record, a.repair_record, a.exit_putInto_record, a.remarks, a.record_id, a.channel_num_light, a.channel_num_inferad from t_robot_info a where 1 = 1 and a.robot_type = #{robotType, jdbcType=INTEGER} and a.robot_status = #{robotStatus, jdbcType=VARCHAR} and a.robot_position = #{robotPosition,jdbcType=INTEGER} and a.is_use = #{isUse,jdbcType=INTEGER} and a.up_region_id in
#{upRegionIds,jdbcType=BIGINT}
ORDER BY robot_id

select a.robot_id, b.robot_name, b.robot_position, b.drone_position, a.inspection_id, a.inspection_name from t_robot_inspection a inner JOIN t_robot_info b ON a.robot_id = b.robot_id WHERE 1 = 1
and a.inspection_type = #{inspectionType, jdbcType=INTEGER}
and a.inspection_name like CONCAT('%',CONCAT(#{name,jdbcType=VARCHAR},'%'))
and b.robot_type is not null
and b.drone_type is not null
and a.robot_id = #{robotId,jdbcType=BIGINT}

select
    a.dict_code
FROM t_dict_business a
where 1 = 1
and a.col_name = #{colName, jdbcType=VARCHAR}
and a.dict_note = #{dictNote, jdbcType=VARCHAR}

select robot_id from t_robot_info
where 1 = 1
 and robot_code = #{robotCode, jdbcType=VARCHAR}

select a.phote_path,a.image_size
FROM t_robot_info a
WHERE a.robot_code = #{robotCode,jdbcType=VARCHAR}
